import type { MetadataRoute } from "next";

/**
 * /robots.txt — auto-generated by Next.js from this route.
 *
 * The full site is allowed. /dev/kit is a designer-only preview so we
 * disallow crawling it.
 */

const SITE_URL =
  process.env.NEXT_PUBLIC_SITE_URL?.replace(/\/$/, "") ||
  "https://darkeye-portfolio.example.com";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        disallow: ["/dev/", "/api/"],
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}
